module up_down_counter (
    input clk,
    input UP,
    input DOWN,
    input reset,
    output reg [2:0] Q
);

always @(posedge clk) begin
    if (reset) begin
        Q <= 3'b000;
    end else if (UP && !DOWN) begin
        Q <= Q + 1;
    end else if (!UP && DOWN) begin
        Q <= Q - 1;
    end
end

