    input  [1:0] sub_out,
    input         select,
    input  a,
    input  b,
    input  c,
    input  d,
    output [31:0] final_out
);

assign final_out = select ? {31'b0, (a & ~b & ~c & ~d) | (~a & b & ~c & ~d)} : {31'b0, sub_out};

endmodule
