  input clk,
  input reset, // Synchronous active-high reset
  input [7:0] in1,
  input [7:0] in2,
  output [7:0] out
);

  reg [7:0] sum;

  always @(posedge clk) begin
    if (reset) begin
      sum <= 8'd0;
    end else begin
      sum <= in1 + in2;
    end
  end

  assign out = sum;

